package com.hereliesaz.stencilartist.core

/**
 * The raster operations the stencil needs, in plain Kotlin so one implementation serves every
 * target. Each reproduces the OpenCV call GraffitiXR's `StencilProcessor` made, border handling
 * included; `RasterGoldenTest` holds them to fixtures generated by OpenCV itself.
 */
object Raster {

    /**
     * Median of the [kernel] x [kernel] neighbourhood of every pixel of an 8-bit plane
     * (`Imgproc.medianBlur`). Pixels beyond the edge repeat the edge pixel. [kernel] must be odd;
     * 1 returns a copy.
     *
     * A sliding histogram per row: moving one pixel right drops one column and adds another, so the
     * cost is O(width * height * kernel), not O(... * kernel^2).
     */
    fun medianBlur(src: ByteArray, width: Int, height: Int, kernel: Int): ByteArray {
        require(src.size == width * height) { "plane size does not match ${width}x$height" }
        require(kernel >= 1 && kernel % 2 == 1) { "a median kernel must be odd and positive, got $kernel" }
        if (kernel == 1 || src.isEmpty()) return src.copyOf()
        val r = kernel / 2
        val half = (kernel * kernel) / 2
        val out = ByteArray(src.size)
        val histogram = IntArray(256)
        for (y in 0 until height) {
            histogram.fill(0)
            // The median is tracked, not searched for: `level` is the smallest level whose cumulative
            // count exceeds half the window, and `upTo` that cumulative count. Adding or dropping a
            // value moves them by one, and the few steps that restore them are cheap on real images.
            var level = 0
            var upTo = 0
            // Rows of the window, clamped to the image (the edge row repeats).
            val rows = IntArray(kernel) { (y - r + it).coerceIn(0, height - 1) * width }
            fun column(x: Int, delta: Int) {
                val cx = x.coerceIn(0, width - 1)
                for (row in rows) {
                    val v = src[row + cx].toInt() and 0xFF
                    histogram[v] += delta
                    if (v <= level) upTo += delta
                }
            }
            for (x in -r..r) column(x, +1)
            for (x in 0 until width) {
                if (x > 0) {
                    column(x - r - 1, -1)
                    column(x + r, +1)
                }
                while (upTo <= half) upTo += histogram[++level]
                while (upTo - histogram[level] > half) upTo -= histogram[level--]
                out[y * width + x] = level.toByte()
            }
        }
        return out
    }

    /**
     * Morphological closing of a binary mask with a [kernel] x [kernel] square: dilate, then erode
     * (`Imgproc.morphologyEx(MORPH_CLOSE)` with a `MORPH_RECT` element). It fills gaps and notches
     * narrower than the kernel, which is what makes a sheet's edge cuttable. Beyond the edge there
     * is nothing: it neither grows the mask nor eats into it. [kernel] 1 returns a copy.
     */
    fun close(mask: BooleanArray, width: Int, height: Int, kernel: Int): BooleanArray {
        require(mask.size == width * height) { "mask size does not match ${width}x$height" }
        require(kernel >= 1) { "a closing kernel must be positive, got $kernel" }
        if (kernel == 1 || mask.isEmpty()) return mask.copyOf()
        val dilated = box(mask, width, height, kernel, any = true)
        return box(dilated, width, height, kernel, any = false)
    }

    /**
     * A square min/max filter, separably: with [any], a pixel is set if any pixel of its window is
     * (dilation); without, only if every in-image pixel of its window is (erosion). The window is
     * anchored as OpenCV anchors it, at `kernel / 2`, which matters for an even kernel.
     */
    private fun box(src: BooleanArray, width: Int, height: Int, kernel: Int, any: Boolean): BooleanArray {
        val before = kernel / 2
        val after = kernel - 1 - before
        fun pass(input: BooleanArray, length: Int, lines: Int, index: (line: Int, i: Int) -> Int): BooleanArray {
            val output = BooleanArray(input.size)
            val prefix = IntArray(length + 1)
            for (line in 0 until lines) {
                for (i in 0 until length) prefix[i + 1] = prefix[i] + if (input[index(line, i)]) 1 else 0
                for (i in 0 until length) {
                    val from = maxOf(0, i - before)
                    val to = minOf(length - 1, i + after)
                    val set = prefix[to + 1] - prefix[from]
                    output[index(line, i)] = if (any) set > 0 else set == to - from + 1
                }
            }
            return output
        }
        val horizontal = pass(src, width, height) { y, x -> y * width + x }
        return pass(horizontal, height, width) { x, y -> y * width + x }
    }

    /**
     * [mask] with every enclosed hole filled: a clear pixel survives only if it can be reached from
     * the edge of the frame through clear pixels, stepping up, down, left or right (the flood
     * GraffitiXR ran with `Imgproc.floodFill` from outside the frame).
     */
    fun fillHoles(mask: BooleanArray, width: Int, height: Int): BooleanArray {
        require(mask.size == width * height) { "mask size does not match ${width}x$height" }
        if (mask.isEmpty()) return mask.copyOf()
        val outside = BooleanArray(mask.size)
        val queue = IntArray(mask.size)
        var head = 0
        var tail = 0
        fun visit(i: Int) {
            if (!mask[i] && !outside[i]) {
                outside[i] = true
                queue[tail++] = i
            }
        }
        for (x in 0 until width) {
            visit(x)
            visit((height - 1) * width + x)
        }
        for (y in 0 until height) {
            visit(y * width)
            visit(y * width + width - 1)
        }
        while (head < tail) {
            val i = queue[head++]
            val x = i % width
            if (x > 0) visit(i - 1)
            if (x < width - 1) visit(i + 1)
            if (i >= width) visit(i - width)
            if (i < mask.size - width) visit(i + width)
        }
        return BooleanArray(mask.size) { !outside[it] }
    }
}
